import heapq

class Solution:
    def kBigIndices(self, nums: list[int], k: int) -> int:
        n = len(nums)
        left_ok = [False] * n
        right_ok = [False] * n
        pq = []
        for i in range(n):
            if len(pq) == k and -pq[0] < nums[i]:
                left_ok[i] = True
            heapq.heappush(pq, -nums[i])
            if len(pq) > k:
                heapq.heappop(pq)
        pq = []
        for i in range(n - 1, -1, -1):
            if len(pq) == k and -pq[0] < nums[i]:
                right_ok[i] = True
            heapq.heappush(pq, -nums[i])
            if len(pq) > k:
                heapq.heappop(pq)
        return sum(1 for i in range(n) if left_ok[i] and right_ok[i])

class Solution {
public:
    int kBigIndices(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<bool> left_ok(n, false), right_ok(n, false);
        std::priority_queue<int> pq;
        for (int i = 0; i < n; ++i) {
            if ((int)pq.size() == k && pq.top() < nums[i]) left_ok[i] = true;
            pq.push(nums[i]);
            if ((int)pq.size() > k) pq.pop();
        }
        while (!pq.empty()) pq.pop();
        for (int i = n - 1; i >= 0; --i) {
            if ((int)pq.size() == k && pq.top() < nums[i]) right_ok[i] = true;
            pq.push(nums[i]);
            if ((int)pq.size() > k) pq.pop();
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (left_ok[i] && right_ok[i]) ans++;
        }
        return ans;
    }
};

class Solution {
    public int kBigIndices(int[] nums, int k) {
        int n = nums.length;
        boolean[] leftOk = new boolean[n];
        boolean[] rightOk = new boolean[n];
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int i = 0; i < n; i++) {
            if (pq.size() == k && pq.peek() < nums[i]) leftOk[i] = true;
            pq.offer(nums[i]);
            if (pq.size() > k) pq.poll();
        }
        pq.clear();
        for (int i = n - 1; i >= 0; i--) {
            if (pq.size() == k && pq.peek() < nums[i]) rightOk[i] = true;
            pq.offer(nums[i]);
            if (pq.size() > k) pq.poll();
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (leftOk[i] && rightOk[i]) ans++;
        }
        return ans;
    }
}

var kBigIndices = function(nums, k) {
    class MaxHeap {
        constructor() { this.data = []; }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            if (this.data.length === 0) return null;
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        peek() { return this.data[0]; }
        size() { return this.data.length; }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[i] > this.data[p]) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.data[left] > this.data[best]) best = left;
                if (right < len && this.data[right] > this.data[best]) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const n = nums.length;
    const leftOk = new Array(n).fill(false);
    const rightOk = new Array(n).fill(false);

    let pq = new MaxHeap();
    for (let i = 0; i < n; i++) {
        if (pq.size() === k && pq.peek() < nums[i]) leftOk[i] = true;
        pq.push(nums[i]);
        if (pq.size() > k) pq.pop();
    }

    pq = new MaxHeap();
    for (let i = n - 1; i >= 0; i--) {
        if (pq.size() === k && pq.peek() < nums[i]) rightOk[i] = true;
        pq.push(nums[i]);
        if (pq.size() > k) pq.pop();
    }

    let ans = 0;
    for (let i = 0; i < n; i++) {
        if (leftOk[i] && rightOk[i]) ans++;
    }
    return ans;
};
